WITH valid AS (SELECT *, CASE WHEN amount >= 1270 THEN 'High' WHEN amount >= 450 THEN 'Medium' ELSE 'Low' END AS amount_tier FROM payments WHERE method = 'promptpay' AND paid_at > TIMESTAMP '2023-11-04 03:00:00') SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, CASE WHEN amount >= 1380 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS span_minutes, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS span_minutes_2, SUM(CASE WHEN method = 'card' THEN amount ELSE 0 END) AS card_amount, SUM(amount) FILTER (WHERE method = 'card') AS card_total_amount, PERCENTILE_APPROX(amount, 0.5) AS amount_p50, GROUPING(DATE_TRUNC('YEAR', paid_at)) AS grouping_level FROM valid GROUP BY ROLLUP (DATE_TRUNC('YEAR', paid_at), CASE WHEN amount >= 1380 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING SUM(CASE WHEN method = 'card' THEN amount ELSE 0 END) > 0
